const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], q = tok[1];
let LOG = 1;
while ((1 << LOG) <= n) LOG++;
const up = Array.from({ length: LOG }, () => new Array(n + 1).fill(1));
const depth = new Array(n + 1).fill(0);
for (let v = 2; v <= n; v++) {
  up[0][v] = tok[v];
  depth[v] = depth[up[0][v]] + 1;
}
for (let k = 1; k < LOG; k++) for (let v = 1; v <= n; v++) up[k][v] = up[k - 1][up[k - 1][v]];
const out = [];
let pos = n + 1;
for (let i = 0; i < q; i++) {
  let u = tok[pos], v = tok[pos + 1];
  pos += 2;
  if (depth[u] < depth[v]) [u, v] = [v, u];
  const diff = depth[u] - depth[v];
  for (let k = 0; k < LOG; k++) if ((diff >> k) & 1) u = up[k][u];
  if (u !== v) {
    for (let k = LOG - 1; k >= 0; k--) if (up[k][u] !== up[k][v]) { u = up[k][u]; v = up[k][v]; }
    u = up[0][u];
  }
  out.push(u);
}
console.log(out.join("\n"));

